    #[test]
    fn hook_names_round_trip() {
        for (i, h) in StepHook::ALL.into_iter().enumerate() {
            assert_eq!(h as usize, i);
            assert_eq!(StepHook::from_name(h.as_str()), Some(h));
        }
        for (i, h) in CondHook::ALL.into_iter().enumerate() {
            assert_eq!(h as usize, i);
            assert_eq!(CondHook::from_name(h.as_str()), Some(h));
        }
        for (i, h) in FilterHook::ALL.into_iter().enumerate() {
            assert_eq!(h as usize, i);
            assert_eq!(FilterHook::from_name(h.as_str()), Some(h));
        }
        for (i, h) in ValueHook::ALL.into_iter().enumerate() {
            assert_eq!(h as usize, i);
            assert_eq!(ValueHook::from_name(h.as_str()), Some(h));
        }
    }
